window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-621a0a467698c908"]={"versions": [{"id": "FIG-621a0a467698c908", "releases": ["R22-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm (Kontrollfluss- und Ablaufdiagramm) zur Spezifikation der Eingangsprüfungen (<code>E2EXf_Inv_input_checks_PXXm</code>) im inversen E2E-Transformer (<code>AUTOSAR_SWS_E2ETransformer</code>). Das Diagramm beschreibt die logische Prüfsequenz beim Empfang/De-Serialisieren transformierter Daten für E2E-Profile mit Methoden- bzw. Header-Unterstützung (PXXm).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li>Startknoten (Initial Node)\n</li><li>Entscheidungsknoten (Decision Nodes):\n<ul class=\"fig-list\"><li><code>Profile == PXXm</code>\n</li><li><code>extractProtocolHeaderFields == NULL</code>\n</li><li><code>csTransactionHandle == NULL</code>\n</li></ul>\n</li><li>Endzustände (Activity Final Nodes):\n<ul class=\"fig-list\"><li>Fehlerhafter/ungültiger Abbruchpfad (linker Endknoten ohne Beschriftung bzw. Standard-Final-Node)\n</li><li>Erfolgreicher Abschluss (<code>return TRUE</code>)\n</li></ul>\n</li><li>Steuerkanten mit Guards: <code>[TRUE]</code>, <code>[FALSE]</code>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Der Kontrollfluss beginnt am Startknoten und prüft, ob das konfigurierte Profil <code>Profile == PXXm</code> entspricht.\n</li><li>Wenn <code>Profile == PXXm</code> <code>[FALSE]</code> ist, wird die Prüfung übersprungen und direkt der Endzustand <code>return TRUE</code> erreicht.\n</li><li>Wenn <code>Profile == PXXm</code> <code>[TRUE]</code> ist, wird geprüft, ob die Funktionsreferenz/Konfiguration <code>extractProtocolHeaderFields == NULL</code> ist:\n<ul class=\"fig-list\"><li>Bei <code>[TRUE]</code> terminiert der Ablauf im linken Endknoten (Fehlerfall/Prüfung fehlgeschlagen).\n</li><li>Bei <code>[FALSE]</code> geht der Fluss zur nächsten Bedingung über.\n</li></ul>\n</li><li>Bei <code>csTransactionHandle == NULL</code>:\n<ul class=\"fig-list\"><li>Bei <code>[TRUE]</code> terminiert der Ablauf im linken Endknoten (Fehlerfall).\n</li><li>Bei <code>[FALSE]</code> terminiert der Ablauf im regulären Erfolgs-Endzustand <code>return TRUE</code>.\n</li></ul>\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm definiert eine normative Vorbedingungsprüfung für die inverse E2E-Transformation bei profilbasierten Methodenaufrufen bzw. Header-Extraktionen (<code>PXXm</code>). Software-Entwickler müssen sicherstellen, dass bei aktivem Profil <code>PXXm</code> sowohl <code>extractProtocolHeaderFields</code> als auch <code>csTransactionHandle</code> gültig initialisiert bzw. ungleich <code>NULL</code> konfiguriert sind, andernfalls wird die Transformation mit Fehler beendet.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-766a52eb7ef70146", "releases": ["R23-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm (Kontrollfluss- und Ablaufdiagramm) zur Spezifikation der Eingangsprüfungen (<code>E2EXf_Inv_input_checks_PXXm</code>) im inversen E2E-Transformer (<code>AUTOSAR_SWS_E2ETransformer</code>) mit Legende der Kommunikationstypen. Das Diagramm beschreibt die logische Prüfsequenz beim Empfang transformierter Daten für E2E-Profile mit Methoden- bzw. Header-Unterstützung (PXXm).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li>Startknoten (Initial Node)\n</li><li>Entscheidungsknoten (Decision Nodes, farbcodiert für „All types“):\n<ul class=\"fig-list\"><li><code>Profile == PXXm</code>\n</li><li><code>extractProtocolHeaderFields == NULL</code>\n</li><li><code>csTransactionHandle == NULL</code>\n</li></ul>\n</li><li>Endzustände (Activity Final Nodes):\n<ul class=\"fig-list\"><li>Fehlerhafter/ungültiger Abbruchpfad (linker Endknoten)\n</li><li>Erfolgreicher Abschluss (<code>return TRUE</code>)\n</li></ul>\n</li><li>Steuerkanten mit Guards: <code>[TRUE]</code>, <code>[FALSE]</code>\n</li><li>Legendenkasten <code>Communication Types</code> mit Farbzuordnungen für:\n<ul class=\"fig-list\"><li>All types (Beige)\n</li><li>Sender/Receiver (Hellgrün)\n</li><li>Publisher/Subscriber (Grün)\n</li><li>C/S: Server (Hellblau)\n</li><li>C/S: Client (Rosa)\n</li><li>Signal to Service (Gelb)\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Der Kontrollfluss beginnt am Startknoten und prüft, ob das konfigurierte Profil <code>Profile == PXXm</code> entspricht.\n</li><li>Wenn <code>Profile == PXXm</code> <code>[FALSE]</code> ist, wird die Prüfung übersprungen und direkt der Endzustand <code>return TRUE</code> erreicht.\n</li><li>Wenn <code>Profile == PXXm</code> <code>[TRUE]</code> ist, wird geprüft, ob die Funktionsreferenz/Konfiguration <code>extractProtocolHeaderFields == NULL</code> ist:\n<ul class=\"fig-list\"><li>Bei <code>[TRUE]</code> terminiert der Ablauf im linken Endknoten (Fehlerfall/Prüfung fehlgeschlagen).\n</li><li>Bei <code>[FALSE]</code> geht der Fluss zur nächsten Bedingung über.\n</li></ul>\n</li><li>Bei <code>csTransactionHandle == NULL</code>:\n<ul class=\"fig-list\"><li>Bei <code>[TRUE]</code> terminiert der Ablauf im linken Endknoten (Fehlerfall).\n</li><li>Bei <code>[FALSE]</code> terminiert der Ablauf im regulären Erfolgs-Endzustand <code>return TRUE</code>.\n</li></ul>\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm definiert eine normative Vorbedingungsprüfung für die inverse E2E-Transformation bei profilbasierten Methodenaufrufen bzw. Header-Extraktionen (<code>PXXm</code>). Software-Entwickler müssen sicherstellen, dass bei aktivem Profil <code>PXXm</code> sowohl <code>extractProtocolHeaderFields</code> als auch <code>csTransactionHandle</code> gültig initialisiert bzw. ungleich <code>NULL</code> konfiguriert sind, andernfalls wird die Transformation mit Fehler beendet.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-655dd39043c755a4", "releases": ["R24-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm (Kontrollfluss- und Ablaufdiagramm) zur Spezifikation der Eingangsprüfungen (<code>E2EXf_Inv_input_checks_PXXm</code>) im inversen E2E-Transformer (<code>AUTOSAR_SWS_E2ETransformer</code>) mit Legende der Kommunikationstypen. Das Diagramm beschreibt die logische Prüfsequenz beim Empfang transformierter Daten für E2E-Profile mit Methoden- bzw. Header-Unterstützung (PXXm).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li>Startknoten (Initial Node)\n</li><li>Entscheidungsknoten (Decision Nodes, farbcodiert für „All types“):\n<ul class=\"fig-list\"><li><code>Profile == PXXm</code>\n</li><li><code>extractProtocolHeaderFields == NULL</code>\n</li><li><code>csTransactionHandle == NULL</code>\n</li></ul>\n</li><li>Endzustände (Activity Final Nodes):\n<ul class=\"fig-list\"><li>Fehlerhafter/ungültiger Abbruchpfad (linker Endknoten)\n</li><li>Erfolgreicher Abschluss (<code>return TRUE</code>)\n</li></ul>\n</li><li>Steuerkanten mit Guards: <code>[TRUE]</code>, <code>[FALSE]</code>\n</li><li>Legendenkasten <code>Legend</code> mit Farbzuordnungen für:\n<ul class=\"fig-list\"><li>All types (Beige)\n</li><li>Sender/Receiver (Hellgrün)\n</li><li>Publisher/Subscriber (Grün)\n</li><li>C/S: Server (Hellblau)\n</li><li>C/S: Client (Rosa)\n</li><li>Signal to Service (Gelb)\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Der Kontrollfluss beginnt am Startknoten und prüft, ob das konfigurierte Profil <code>Profile == PXXm</code> entspricht.\n</li><li>Wenn <code>Profile == PXXm</code> <code>[FALSE]</code> ist, wird die Prüfung übersprungen und direkt der Endzustand <code>return TRUE</code> erreicht.\n</li><li>Wenn <code>Profile == PXXm</code> <code>[TRUE]</code> ist, wird geprüft, ob die Funktionsreferenz/Konfiguration <code>extractProtocolHeaderFields == NULL</code> ist:\n<ul class=\"fig-list\"><li>Bei <code>[TRUE]</code> terminiert der Ablauf im linken Endknoten (Fehlerfall/Prüfung fehlgeschlagen).\n</li><li>Bei <code>[FALSE]</code> geht der Fluss zur nächsten Bedingung über.\n</li></ul>\n</li><li>Bei <code>csTransactionHandle == NULL</code>:\n<ul class=\"fig-list\"><li>Bei <code>[TRUE]</code> terminiert der Ablauf im linken Endknoten (Fehlerfall).\n</li><li>Bei <code>[FALSE]</code> terminiert der Ablauf im regulären Erfolgs-Endzustand <code>return TRUE</code>.\n</li></ul>\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm definiert eine normative Vorbedingungsprüfung für die inverse E2E-Transformation bei profilbasierten Methodenaufrufen bzw. Header-Extraktionen (<code>PXXm</code>). Software-Entwickler müssen sicherstellen, dass bei aktivem Profil <code>PXXm</code> sowohl <code>extractProtocolHeaderFields</code> als auch <code>csTransactionHandle</code> gültig initialisiert bzw. ungleich <code>NULL</code> konfiguriert sind, andernfalls wird die Transformation mit Fehler beendet.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-2bc86ea52b670f6a", "releases": ["R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm (Kontrollfluss- und Ablaufdiagramm) zur Spezifikation der Eingangsprüfungen (<code>E2EXf_Inv_input_checks_PXXm</code>) im inversen E2E-Transformer (<code>AUTOSAR_SWS_E2ETransformer</code>) mit Legende der Kommunikationstypen. Das Diagramm beschreibt die logische Prüfsequenz beim Empfang transformierter Daten für E2E-Profile mit Methoden- bzw. Header-Unterstützung (PXXm).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li>Startknoten (Initial Node)\n</li><li>Entscheidungsknoten (Decision Nodes, farbcodiert für „All types“):\n<ul class=\"fig-list\"><li><code>Profile == PXXm</code>\n</li><li><code>extractProtocolHeaderFields == NULL</code>\n</li></ul>\n</li><li>Endzustände (Activity Final Nodes):\n<ul class=\"fig-list\"><li>Fehlerhafter/ungültiger Abbruchpfad (linker Endknoten)\n</li><li>Erfolgreicher Abschluss (<code>return TRUE</code>)\n</li></ul>\n</li><li>Steuerkanten mit Guards: <code>[TRUE]</code>, <code>[FALSE]</code>\n</li><li>Legendenkasten <code>Legend</code> mit Farbzuordnungen für:\n<ul class=\"fig-list\"><li>All types (Beige)\n</li><li>Sender/Receiver (Hellgrün)\n</li><li>Publisher/Subscriber (Grün)\n</li><li>C/S: Server (Hellblau)\n</li><li>C/S: Client (Rosa)\n</li><li>Signal to Service (Gelb)\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Der Kontrollfluss beginnt am Startknoten und prüft, ob <code>Profile == PXXm</code> gilt.\n</li><li>Wenn <code>Profile == PXXm</code> <code>[FALSE]</code> ist, wechselt der Kontrollfluss direkt zum Endzustand <code>return TRUE</code>.\n</li><li>Wenn <code>Profile == PXXm</code> <code>[TRUE]</code> ist, wird geprüft, ob <code>extractProtocolHeaderFields == NULL</code> gilt:\n<ul class=\"fig-list\"><li>Bei <code>[TRUE]</code> terminiert der Ablauf im linken Endknoten (Fehlerabbruch).\n</li><li>Bei <code>[FALSE]</code> terminiert der Ablauf direkt im regulären Endzustand <code>return TRUE</code>.\n</li></ul>\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm definiert eine normative Vorbedingungsprüfung für die inverse E2E-Transformation beim Profil <code>PXXm</code>. Bei konfiguriertem Profil <code>PXXm</code> ist ausschließlich das Vorhandensein der Header-Extraktionsfunktion (<code>extractProtocolHeaderFields != NULL</code>) Voraussetzung für die Fortsetzung; eine Prüfung auf <code>csTransactionHandle</code> findet an dieser Stelle nicht statt.</p>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-621a0a467698c908", "to": "FIG-766a52eb7ef70146", "fr": "R22-11", "tr": "R23-11", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\"><li>Oben links wurde ein Legendenkasten („Communication Types“) ergänzt, der Farbcodierungen für Kommunikationstypen aufführt (All types, Sender/Receiver, Publisher/Subscriber, C/S: Server, C/S: Client, Signal to Service).\n</li><li>Die Entscheidungsknoten im Aktivitätsdiagramm sind gemäß dem Farbcode für „All types“ eingefärbt.\n</li></ul>"}, {"from": "FIG-766a52eb7ef70146", "to": "FIG-655dd39043c755a4", "fr": "R23-11", "tr": "R24-11", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\"><li>Die Überschrift des Legendenkastens wurde von „Communication Types“ zu „Legend“ geändert.\n</li></ul>"}, {"from": "FIG-655dd39043c755a4", "to": "FIG-2bc86ea52b670f6a", "fr": "R24-11", "tr": "R25-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li>Der Entscheidungsknoten <code>csTransactionHandle == NULL</code> und dessen ausgehende Kanten (<code>[TRUE]</code> zum linken Endzustand, <code>[FALSE]</code> zum Endzustand <code>return TRUE</code>) wurden entfernt.\n</li><li>Der Zweig <code>[FALSE]</code> der Bedingung <code>extractProtocolHeaderFields == NULL</code> führt nun direkt zum Endzustand <code>return TRUE</code>.\n</li></ul>"}]};
